function validate([target, arr]) {
  if (!Array.isArray(target) || target.length < 1 || target.length > 100000) return 'target needs 1 to 10^5 values.';
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 10^5 values.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 1e9;
  if (!target.every(ok)) return 'Each value of target is an integer from 1 to 10^9.';
  if (!arr.every(ok)) return 'Each value of arr is an integer from 1 to 10^9.';
  if (new Set(target).size !== target.length) return 'target must not contain duplicates.';
  return null;
}

