function minOperations(target, arr) {
  // Plain longest common subsequence table.
  const n = target.length, m = arr.length;
  const table = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = 1; i <= n; i++)
    for (let j = 1; j <= m; j++)
      table[i][j] = target[i - 1] === arr[j - 1] ? table[i - 1][j - 1] + 1 : Math.max(table[i - 1][j], table[i][j - 1]);
  return n - table[n][m];
}

