function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = pick(1500, 2000);
    const seen = new Set();
    const target = [];
    while (target.length < n) {
      const v = pick(1, 1e9);
      if (!seen.has(v)) { seen.add(v); target.push(v); }
    }
    const m = pick(1500, 2000);
    const arr = Array.from({ length: m }, () => (rand() < 0.8 ? target[pick(0, n - 1)] : pick(1, 1e9)));
    return [target, arr];
  }
  const range = pick(3, 12);
  const pool = Array.from({ length: range }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const target = pool.slice(0, pick(1, Math.min(7, range)));
  const arr = Array.from({ length: pick(1, 9) }, () => pick(1, range + 2));
  return [target, arr];
}
